slots.drawFrame:
const r = 0.25;
const px = 8.0;
const py = state.e0.cy;
const bx = px + r;
const cx2 = px + r;

// 传送带
Draw.belt([-4, 0], [7.4, 0], { ticks: 26, tickPhase: t * 0.8 });

// 定滑轮与支撑
Draw.line([px, py + r], [px, py + r + 0.45]);
Draw.line([px - 0.15, py + r + 0.45], [px + 1.1, py + r + 0.45]);
Draw.pulley([px, py], r);

// 绳子：水平段切左缘，绕过滑轮上半圈，竖直段切右缘
Draw.line([state.e0.cx, py], [px - r, py]);
Draw.arc([px, py], r, 180, 360);
Draw.line([bx, py], [bx, state.e1.cy]);
Draw.box([state.e0.cx, state.e0.cy], state.e0.w, state.e0.h);
Draw.box([bx, state.e1.cy], state.e1.w, state.e1.h);
if (t <= 2.051434) {
  Draw.line([bx, state.e1.cy], [cx2, state.e2.cy]);
  Draw.box([cx2, state.e2.cy], state.e2.w, state.e2.h);
}

slots.readouts:
// 由 analysis 运动表生成；曲线图直接读这里
const out = [];
const h = 1e-4;
const tA = Math.max(0, t - h);
const tB = Math.min(3.62223, t + h);
const a = stateAt(tA);
const b = stateAt(tB);
const dt = (tB - tA) || 1;
out.push({ key: "A.x", label: "A 水平位置", value: state.e0.x, unit: 'm' });
out.push({ key: "A.y", label: "A 竖直位置", value: state.e0.y, unit: 'm' });
out.push({ key: "A.vx", label: "A 水平速度", value: (b.e0.x - a.e0.x) / dt, unit: 'm/s' });
out.push({ key: "A.vy", label: "A 竖直速度", value: (b.e0.y - a.e0.y) / dt, unit: 'm/s' });
out.push({ key: "B.x", label: "B 水平位置", value: state.e1.x, unit: 'm' });
out.push({ key: "B.y", label: "B 竖直位置", value: state.e1.y, unit: 'm' });
out.push({ key: "B.vx", label: "B 水平速度", value: (b.e1.x - a.e1.x) / dt, unit: 'm/s' });
out.push({ key: "B.vy", label: "B 竖直速度", value: (b.e1.y - a.e1.y) / dt, unit: 'm/s' });
out.push({ key: "C.x", label: "C 水平位置", value: state.e2.x, unit: 'm' });
out.push({ key: "C.y", label: "C 竖直位置", value: state.e2.y, unit: 'm' });
out.push({ key: "C.vx", label: "C 水平速度", value: (b.e2.x - a.e2.x) / dt, unit: 'm/s' });
out.push({ key: "C.vy", label: "C 竖直速度", value: (b.e2.y - a.e2.y) / dt, unit: 'm/s' });
return out;
